};
const { renameSync } = await import('fs');
const { join } = await import('path');
const { execFileSync } = await import('child_process');
const fixturePath = join($root, 'packages/main/tests/fixtures/store-state-entries.json');
const backupPath = fixturePath + '.bak';
renameSync(fixturePath, backupPath);
try {
  const raw = execFileSync('koala', ['gap_analyze', '--format=json'], { cwd: $root, encoding: 'utf8' });
  const data = parseCliJson(raw);
  const unrelatedGaps = data.gaps.filter(g => String(g.description || '').includes('store-state-entries.json')).length;
  const targetGaps = data.gaps.filter(g => /cli-flags\.json|metadata-cross-check\.json/.test(String(g.description || ''))).length;
  return { unrelatedGaps, targetGaps };
} finally {
  renameSync(backupPath, fixturePath);
}

